use std::{env,fs};use candid::{Encode,Decode,Principal};use serde_json::json;use sha2::{Digest,Sha256};use imajev_quantize_scan_bench::{Measurement,reference};fn main(){let a:Vec<String>=env::args().collect();match a[1].as_str(){"init"=>fs::write(&a[3],Encode!(&Principal::from_text(&a[2]).unwrap()).unwrap()).unwrap(),"query"=>{let x=fs::read(&a[2]).unwrap();let c:u32=a[3].parse().unwrap();let method:u8=a[4].parse().unwrap();fs::write(&a[5],Encode!(&x,&c,&method).unwrap()).unwrap();},"native"=>{let x:Vec<f32>=fs::read(&a[2]).unwrap().chunks_exact(4).map(|v|f32::from_le_bytes(v.try_into().unwrap())).collect();let c:usize=a[3].parse().unwrap();match reference(&x,x.len()/c,c){Ok(b)=>println!("{}",json!({"digest":Sha256::digest(b).iter().map(|v|format!("{v:02x}")).collect::<String>()})),Err(e)=>println!("{}",json!({"error":e}))}},"decode"=>{let h=fs::read_to_string(&a[2]).unwrap();let h=h.trim();let b:Vec<u8>=(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect();let r=Decode!(&b,Result<Measurement,String>).unwrap();match r{Ok(m)=>println!("{}",json!({"digest":m.digest.iter().map(|v|format!("{v:02x}")).collect::<String>(),"instructions":m.instructions,"values":m.values,"scales":m.scales})),Err(e)=>println!("{}",json!({"error":e}))}},_=>panic!("command")}}
